INSERT INTO content_items (id, creator_id, platform, external_id, title, description, url, thumbnail_url, views, likes, published_at, created_at, updated_at, duration_seconds, comments, tags_json, transcript, transcript_source, thumbnail_analysis_json, analysis_json, analysis_status, analysis_error, analyzed_by, analyzed_at) VALUES ('ci_521cf04b-de8', 'creator_demo_tech_kabir', 'youtube', 'U_uO57F2GPE', 'Jio''s AirTag? JioFind 4G SIM Tracker Unboxing and First Look', 'Jio''s AirTag? Not quite. This is the JioFind 4G, a SIM-based 4G tracker, not a Bluetooth tracker like JioTag or Apple AirTag.

In this video I unbox the JioFind 4G and show you what is in the box: the tracker, a Type-C cable, and a Jio SIM card. It has a power button, a SIM card slot, and a Type-C port for charging.

You set it up with the JioThings app from the Play Store, via a QR code. It gives you live location tracking, location history, geofencing, low battery alerts, overspeed alerts, device off alerts, and voice monitoring.

Geofencing example: set a radius around your office or home, and when your device reaches home, you get a notification that your device is home. You can put it on your bike, in your car, or anywhere inside.

This is just an unboxing and first look, not a full test yet. I bought it for a project, and then it just went into my cupboard.

Do you want a detailed testing video comparing it with an Apple AirTag? Like real location, real geofence, and real battery test? Tell me in the comments.

