-- lessons: 4 rows
INSERT INTO lessons (id, creator_id, gap_node_id, order_index, title, category, duration_min, content_markdown, completed, completed_at, created_at) VALUES ('lesson_bc3d1001-d9d', 'creator_demo_tech_kabir', 'node_6077017e-756', 1, 'Titles that survive the mobile cut', 'Packaging', 5, 'Mobile feeds show roughly the first 50 characters of a title.

1. Put the subject and the payoff in those first 50 characters
2. Use one concrete number: a price, a duration or a count
3. Move qualifiers like "honest" or "in 2026" to the end

**Try it:** rewrite your last three titles so the payoff lands before character 50.', 0, NULL, '2026-11-14T13:41:00.912Z');
INSERT INTO lessons (id, creator_id, gap_node_id, order_index, title, category, duration_min, content_markdown, completed, completed_at, created_at) VALUES ('lesson_34eb5cc4-a6d', 'creator_demo_tech_kabir', 'node_5294a4e7-bd4', 2, 'The first five seconds', 'Retention', 5, 'Viewers decide in the opening seconds whether the video keeps the title''s promise.

1. Open on the result, the reveal or the question
2. Skip channel intros and greetings before the hook
3. Promise one specific thing that comes later and name when

**Try it:** script only the first two sentences of your next video and read them aloud.', 0, NULL, '2026-11-14T13:41:00.912Z');
INSERT INTO lessons (id, creator_id, gap_node_id, order_index, title, category, duration_min, content_markdown, completed, completed_at, created_at) VALUES ('lesson_21554584-eae', 'creator_demo_tech_kabir', NULL, 3, 'Descriptions that get found', 'SEO', 5, 'Search reads your title, description and chapters.

1. Repeat the main search phrase in the first line of the description
2. Add chapters with plain, searchable names
3. Link related uploads at the end

**Try it:** add chapters to your three most viewed videos.', 0, NULL, '2026-11-14T13:41:00.912Z');
INSERT INTO lessons (id, creator_id, gap_node_id, order_index, title, category, duration_min, content_markdown, completed, completed_at, created_at) VALUES ('lesson_bfa692e4-743', 'creator_demo_tech_kabir', NULL, 4, 'Say it the way you talk', 'Voice', 5, 'Your best-performing uploads usually sound like you on a good day.

1. Write the outline, not the sentences
2. Keep your recurring phrases; they are recognition, not filler
3. Cut anything you would never say to a friend

**Try it:** record a one-minute voice note explaining your next topic, then outline from it.', 0, NULL, '2026-11-14T13:41:00.912Z');

-- quizzes: 1 rows
INSERT INTO quizzes (id, creator_id, gap_node_id, title, questions_json, score, status, completed_at, created_at) VALUES ('quiz_6e578b2e-c0a', 'creator_demo_tech_kabir', 'node_6077017e-756', 'Baseline: packaging, retention and compliance', '[{"id":"q1","question":"Roughly how many characters of a title show in a mobile feed before it is cut?","options":["20","About 50","100","All of it"],"correctIndex":1,"explanation":"Mobile layouts cut titles near 50 characters, so the payoff belongs at the start."},{"id":"q2","question":"What belongs in the first five seconds of a video?","options":["A channel intro","A request to subscribe","The result or question the title promised","Background music only"],"correctIndex":2,"explanation":"Opening on the promised payoff keeps viewers who clicked for it."},{"id":"q3","question":"Which change most helps a video get found in search?","options":["More hashtags","The main search phrase in the first line of the description","A longer outro","Disabling comments"],"correctIndex":1,"explanation":"Search weighs the opening of the description and the title most."},{"id":"q4","question":"What is the safest way to keep your natural voice in a scripted video?","options":["Read a full script word for word","Outline points and speak them in your own words","Copy a bigger creator''s phrasing","Avoid recurring phrases"],"correctIndex":1,"explanation":"An outline keeps structure while the delivery stays yours."},{"id":"q5","question":"Which title is more likely to earn a click on mobile?","options":["My honest and complete thoughts after using it for a while","Used it 30 days: 3 things nobody mentions","Video #42","Watch this"],"correctIndex":1,"explanation":"Front-loaded, concrete titles with a number read fastest."}]', NULL, 'pending', NULL, '2026-11-14T13:41:00.912Z');

