INSERT INTO assets (id, project_id, creator_id, type, current_version_id, title, content, created_at, updated_at) VALUES ('asset_proj_1794663665250_fg2d_instagram_caption', 'proj_1794663665250_fg2d', 'creator_demo_tech_kabir', 'instagram_caption', 'v_asset_proj_1794663665250_fg2d_instagram_caption_1', 'Instagram Reel Caption', '"Need a USB-C hub that won''t break the bank? We''ve got you covered! Check out our latest video (link in bio) for the top 3 budget picks and let us know which one you''d choose! #USBCHub #BudgetTech #LaptopAccessories"

**7. 8-Minute Video Script Outline:**
I. Introduction (0:00 - 0:30)
